/// What a crate root holds that CANNOT cross into an `include!`d file, each named with its home.
///
/// ESTABLISHED EMPIRICALLY, and the answer is narrower than the folklore. Measured over all 66 crate
/// roots in this tree on 2026-09-05:
///
/// * `//!` crate docs — 62 roots. NOT a blocker: the shared root's `#![doc = include_str!(…)]` takes
///   them, and [`crate_doc_markdown`] is how they get there. This was the one everybody believed was
///   fatal, and it is the one that already worked.
/// * `#![…]` inner attributes — THREE, all in binaries: two `#![forbid(unsafe_code)]` and
///   `src-tauri`'s `#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]`. A real
///   blocker: an inner attribute in an included file is not merely a doc-comment error, it is not
///   permitted at all. The lint ones have a manifest home (`[lints.rust] unsafe_code = "forbid"`);
///   `cfg_attr(windows_subsystem)` has none, which is why `src-tauri/src/main.rs` is named in the
///   report as NOT a candidate rather than forced.
/// * `extern crate` — ZERO. The 2018 edition removed the need, and this repo has none, so the shape
///   is refused here on principle rather than on evidence: it binds a name into the CRATE root, and
///   an included file is not one.
///
/// A `pub use` prelude is NOT a blocker and was the third thing the item asked about: a re-export is
/// an ordinary item, and `bsc-sqlite-util` — `pub use bsc_util::home_dir;` at the top and
/// `pub use conn::{…}` past an inline `mod conn` — materializes with both intact.
pub fn root_blockers(root_src: &str) -> Vec<String> {
    let mut out = Vec::new();
    for line in root_src.lines() {
        let t = line.trim();
        // `#![doc = …]` is the one inner attribute the shared root itself carries, so a root that has
        // already been given one is not blocked by it.
        if t.starts_with("#![") && !t.starts_with("#![doc") {
            out.push(t.to_string());
        }
        if t.starts_with("extern crate ") {
            out.push(t.to_string());
        }
    }
    out
}
